<?php
declare(strict_types=1);require_once __DIR__.'/../auth_check.php';require_once __DIR__.'/../model/Database.php';require_once __DIR__.'/../services/MeetingDailyFollowupService.php';require_once __DIR__.'/../vendor/autoload.php';
use PhpOffice\PhpSpreadsheet\Spreadsheet;use PhpOffice\PhpSpreadsheet\Writer\Xlsx;use PhpOffice\PhpSpreadsheet\Style\Fill;use PhpOffice\PhpSpreadsheet\Style\Border;use PhpOffice\PhpSpreadsheet\Style\Alignment;
$uid=(int)($_SESSION['user_id']??0);$rows=(new MeetingDailyFollowupService(Database::getConnection()))->exportRows($uid);$labels=['pending'=>'En attente de réponse','completed'=>'Terminée','rescheduled'=>'Exécution reportée','remind'=>'Rappel demandé','decision_deferred'=>'Décision reportée'];$name=trim((string)($_SESSION['user_name']??($_SESSION['prenom']??'').' '.($_SESSION['nom']??'')))?:'Utilisateur';
$book=new Spreadsheet();$sheet=$book->getActiveSheet();$sheet->setTitle('Suivi réunions');$sheet->mergeCells('A1:M1')->setCellValue('A1','SUIVI DES ENGAGEMENTS DE RÉUNION');$sheet->mergeCells('A2:M2')->setCellValue('A2','Collaborateur : '.$name.' · Exporté le '.date('d/m/Y à H:i'));$sheet->mergeCells('A3:M3')->setCellValue('A3',count($rows).' élément(s) de suivi · Points en attente et historique pilote/copilote');
$headers=['Date réponse','Réunion','Service / Chantier','Rubrique','Point principal','Sous-tâche','Rôle','Décision','Date d’exécution','Prochain rappel','Reports','Écart (jours)','Commentaire'];$sheet->fromArray($headers,null,'A5');$line=6;foreach($rows as$r){$sheet->fromArray([$r['response_date'],$r['meeting_title'],$r['group_label'],$r['section_title'],$r['task_title'],$r['checklist_label'],$r['role_label'],$labels[$r['response_type']]??$r['response_type'],$r['execution_date'],$r['next_prompt_at'],(int)$r['reschedule_count'],(int)$r['total_shift_days'],$r['note']],null,'A'.$line);$line++;}
$last=max(6,$line-1);$sheet->getStyle('A1:M1')->getFont()->setBold(true)->setSize(18)->getColor()->setRGB('FFFFFF');$sheet->getStyle('A1:M1')->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setRGB('111D3B');$sheet->getRowDimension(1)->setRowHeight(30);$sheet->getStyle('A2:M3')->getFont()->getColor()->setRGB('475569');$sheet->getStyle('A5:M5')->getFont()->setBold(true)->getColor()->setRGB('FFFFFF');$sheet->getStyle('A5:M5')->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setRGB('3730A3');$sheet->getStyle('A5:M'.$last)->getBorders()->getAllBorders()->setBorderStyle(Border::BORDER_THIN)->getColor()->setRGB('CBD5E1');$sheet->getStyle('A6:M'.$last)->getAlignment()->setVertical(Alignment::VERTICAL_TOP)->setWrapText(true);for($r=6;$r<=$last;$r++)if($r%2===0)$sheet->getStyle('A'.$r.':M'.$r)->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setRGB('F8FAFC');
